<script>
  import ArcIcon from '../../components/ArcIcon.svelte'
  export let data; export let diagnostics = {}; export let diagnosticNode = ''; export let onDiagnostic
  let filter = 'all'
  $: nodes = (data?.remnawave?.nodes || []).filter(node => !/finland lte/i.test(node.name || ''))
  $: edges = data?.remnawave?.lte_edges || []
  $: visible = nodes.filter(node => filter === 'all' || (filter === 'online' ? node.connected : !node.connected))
  const speed = value => Number(value || 0) >= 1_000_000 ? `${(Number(value) / 1_000_000).toFixed(1)} МБ/с` : `${Math.round(Number(value || 0) / 1000)} КБ/с`
</script>

<section class="page">
  <header><span>ИНФРАСТРУКТУРА</span><h2>Ноды и LTE-контур</h2><p>Физические RemnaNode и отдельные CDN-маршруты, которые включаются при глушении.</p></header>
  <section class="edge-board" aria-label="LTE маршруты">
    <header><div><small>АВАРИЙНЫЙ КОНТУР</small><b>CDN → origin → XHTTP</b></div><em>{edges.filter(edge => edge.healthy).length}/{edges.length} готовы</em></header>
    <div class="edge-grid">{#each edges as edge}<article class:off={!edge.healthy}>
      <div class="edge-title"><i>{edge.country_code}</i><span><b>{edge.name}</b><small>{edge.profile_name}</small></span><em>{edge.healthy ? 'READY' : 'DEGRADED'}</em></div>
      <div class="rail"><span>{edge.public_host}</span><i>CDN</i><span>{edge.origin || 'origin не найден'}</span><i>:{edge.port}</i><span>{String(edge.network || 'xhttp').toUpperCase()}</span></div>
      <dl><div><dt>Inbound</dt><dd>{edge.inbound_active ? 'активен' : 'не найден'}</dd></div><div><dt>Путь</dt><dd>{edge.path}</dd></div><div><dt>Трафик</dt><dd>×{edge.traffic_factor}</dd></div><div><dt>Онлайн на origin</dt><dd>{edge.users_online || 0}</dd></div></dl>
    </article>{/each}</div>
  </section>
  <nav><button class:active={filter==='all'} on:click={()=>filter='all'}>Все <i>{nodes.length}</i></button><button class:active={filter==='online'} on:click={()=>filter='online'}>Онлайн <i>{nodes.filter(n=>n.connected).length}</i></button><button class:active={filter==='problems'} on:click={()=>filter='problems'}>Проблемы <i>{nodes.filter(n=>!n.connected).length}</i></button></nav>
  <div class="nodes">{#each visible as node}<article class:off={!node.connected}>
    <header><i>{node.country_code || '—'}</i><span><b>{node.name}</b><small>{node.address}</small></span><em>{node.connected?'ONLINE':'OFFLINE'}</em></header>
    <div class="stats"><span><small>ОНЛАЙН</small><b>{node.users_online||0}</b></span><span><small>ТРАФИК</small><b>{node.traffic_used_gb||0} ГБ</b></span><span><small>RAM</small><b>{node.memory_used_pct||0}%</b></span><span><small>СЕТЬ</small><b>{speed((node.rx_bps||0)+(node.tx_bps||0))}</b></span></div>
    <div class="inbounds">{#each node.inbounds||[] as inbound}<span>{String(inbound.network||inbound.type||'').toUpperCase()} <b>:{inbound.port}</b><small>{inbound.tag}</small></span>{/each}</div>
    {#if diagnostics[node.uuid]}<p class:good={diagnostics[node.uuid].ok}>{diagnostics[node.uuid].ok ? `Тест пройден за ${diagnostics[node.uuid].duration_ms} мс` : `Ошибка: ${diagnostics[node.uuid].error}`}</p>{/if}
    <button class="test" disabled={diagnosticNode===node.uuid} on:click={()=>onDiagnostic(node)}><ArcIcon name="pulse" size={16}/>{diagnosticNode===node.uuid?'Проверяем…':'Глубокий тест'}</button>
  </article>{/each}</div>
</section>

<style>
.page{display:grid;gap:20px}.page>header span,.edge-board small{color:#80c9f4;font-size:10px;font-weight:900;letter-spacing:.15em}.page h2{margin:8px 0 5px;font-size:30px}.page p,.page>header p{margin:0;color:#7890a5}.edge-board{overflow:hidden;border:1px solid rgba(120,210,255,.16);border-radius:24px;background:linear-gradient(135deg,#0b1622,#101c29)}.edge-board>header{display:flex;align-items:center;justify-content:space-between;padding:18px 20px;border-bottom:1px solid rgba(255,255,255,.06)}.edge-board>header div{display:grid;gap:4px}.edge-board>header em{color:#78e1b4;font-size:11px;font-style:normal}.edge-grid{display:grid;grid-template-columns:1fr 1fr}.edge-grid article{padding:20px}.edge-grid article+article{border-left:1px solid rgba(255,255,255,.06)}.edge-grid article.off{background:rgba(255,100,110,.035)}.edge-title{display:flex;align-items:center;gap:11px}.edge-title>i,.nodes header>i{display:grid;width:44px;height:44px;place-items:center;border-radius:15px;background:#15314a;color:#9bd9ff;font-style:normal;font-weight:900}.edge-title span{display:grid;flex:1}.edge-title small{color:#7890a5;letter-spacing:0}.edge-title em,.nodes header em{padding:7px 9px;border-radius:10px;background:#123127;color:#75ddb0;font-size:9px;font-style:normal;font-weight:900}.off .edge-title em,.nodes .off header em{background:#351d26;color:#ff9c9c}.rail{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr) auto auto;align-items:center;gap:7px;margin:18px 0;padding:11px;border-radius:14px;background:#08111a;color:#afc5d7;font:10px ui-monospace,SFMono-Regular,monospace}.rail span{overflow:hidden;text-overflow:ellipsis}.rail i{color:#5e7d95;font-style:normal}.edge-grid dl{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:0}.edge-grid dl div{padding:9px;border-radius:11px;background:rgba(255,255,255,.025)}dt{color:#637b8e;font-size:9px}dd{margin:4px 0 0;color:#dcecf7;font-size:11px}.page>nav{display:flex;gap:7px}.page>nav button{padding:10px 14px;border:0;border-radius:13px;background:#101b29;color:#7890a5}.page>nav button.active{background:#9bd9ff;color:#07111d}.page>nav i{margin-left:5px;font-style:normal}.nodes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.nodes>article{padding:21px;border:1px solid rgba(155,217,255,.1);border-radius:24px;background:linear-gradient(150deg,#101b29,#09121d)}.nodes>article.off{opacity:.72;border-color:rgba(255,121,121,.2)}.nodes article>header{display:flex;align-items:center;gap:11px}.nodes header>span{display:flex;flex:1;flex-direction:column}.nodes header small{color:#7890a5}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:20px 0}.stats span{padding:12px;border-radius:15px;background:#0d1825}.stats small,.stats b{display:block}.stats small{color:#6f879b;font-size:8px}.stats b{margin-top:7px}.inbounds{display:flex;flex-wrap:wrap;gap:6px}.inbounds span{display:grid;padding:7px 9px;border-radius:11px;background:#0d1825;color:#93aabd;font-size:10px}.inbounds b{color:#9bd9ff}.inbounds small{max-width:190px;overflow:hidden;color:#526b7f;text-overflow:ellipsis}.test{display:flex;width:100%;justify-content:center;gap:8px;margin-top:18px;padding:12px;border:1px solid rgba(155,217,255,.14);border-radius:14px;background:#14283a;color:#bde7ff;font-weight:900}.nodes p.good{color:#75d8aa}@media(max-width:950px){.edge-grid,.nodes{grid-template-columns:1fr}.edge-grid article+article{border-top:1px solid rgba(255,255,255,.06);border-left:0}.stats{grid-template-columns:1fr 1fr}.rail{grid-template-columns:1fr auto}.rail i{display:none}}
</style>
